j=lambda name:json.loads((root/name).read_text(encoding='utf-8-sig'))
s=j('profile-summary.json');a=j('phase-attribution.json');f=j('diagnostic-findings.json');ident=j('identity.json');proc=s['process'];last=f['last_process_sample']
labels={'phase.storage_capacity':'Вместимость складов','phase.arrivals':'Прибытие грузов','phase.mobility':'Мобильность и труд','phase.budget_opening':'Открытие бюджетов','phase.investments':'Инвестиции','phase.artisan_opening':'Открытие ремесленных доходов','phase.service_payroll':'Выплаты за услуги','phase.maintenance':'Содержание (maintenance)'}
